-- Zul'Drak: combat SmartAI for 28 creatures that cast no spell here and had no AI.
-- Rows from 5.4.8 (Legends of Azeroth), taken only where every event, action and target type is numbered the same in this core,
-- every spell is in the client data and 3.3.5 casts at least half of the same spells. Quest, summon and waypoint scripts are not included.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (16570,26965,28035,28036,28156,28233,28303,28323,28412,28418,28452,28465,28597,28793,28848,28882,28917,29133,29235,29236,29237,29332,29334,29646,29654,29656,29664,29697) AND `ScriptName` = '';
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (16570,26965,28035,28036,28156,28233,28303,28323,28412,28418,28452,28465,28597,28793,28848,28882,28917,29133,29235,29236,29237,29332,29334,29646,29654,29656,29664,29697);
DELETE FROM `creature_text` WHERE `entry` IN (28793,28917);
